const { House } = await import('file:///tmp/house-check.mjs');
const assert = (ok, msg) => { if (!ok) throw new Error(msg); };
const eq = (actual, expected, msg) => assert(JSON.stringify(actual) === JSON.stringify(expected), msg);

eq(House.verses(3, 3), House.verse(3), 'single-verse range');
assert(House.verses(2, 1).length === 0, 'reverse range should be empty');
eq(House.verses(1, 2), [...House.verse(1), '', ...House.verse(2)], 'blank separator');

const before = JSON.stringify(House.verse(12));
House.verse(1);
House.verses(4, 8);
assert(JSON.stringify(House.verse(12)) === before, 'calls should not mutate state');

for (const invalid of [0, -1, 13, 1.5, '1', null, undefined]) {
  let threw = false;
  try { House.verse(invalid); } catch (error) { threw = error instanceof RangeError; }
  assert(threw, `invalid verse ${String(invalid)} should throw RangeError`);
}

console.log('edge checks passed');
